// Minimal adversarial helper that implements supportsToken() and re-enters C.airDrop during that call.
// It will call c.airDrop() as itself while C is mid-airDrop if the reentrancy guard is missing.
contract MaliciousBank {
    C immutable target;
    address public victim;
    bool public reentered;

    constructor(C _target, address _victim) {
        target = _target;
        victim = _victim;
        reentered = false;
    }

    // This function will be called by the test to start the attack. It calls target.airDrop().
    function doAirdrop() external {
        // Call airDrop as this contract (msg.sender == address(this)).
        target.airDrop();
    }

    // C.supportsToken() expects external pure returns (bytes32) in Bank interface; we implement it
    // but with side-effect: on first invocation, attempt to re-enter target.airDrop() to exploit missing lock.
    function supportsToken() external returns (bytes32) {
        // On first call, attempt re-entry
        if (!reentered) {
            reentered = true;
            // Attempt to re-enter airDrop; if guarded, this will revert and be ignored by caller, but
            // we catch nothing here — reverts will surface. The test wraps doAirdrop() in try/catch.
            // We call target.airDrop() to try to alter balances for victim or self.
            // We first set up victim to have zero (it is already zero by default), then in the reentrant
            // call we will make the target try to credit this contract or victim depending on code.
            // This re-entry is what distinguishes the mutant.
            // Use a low-level call to avoid static checks; but calling the function directly is fine.
            // We ignore any revert here to allow execution to continue in the outer call.
            // Use a try/catch to suppress revert propagation.
            try target.airDrop() {
            } catch {
            }
        }
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

